#include "../include/top.h"
#include <algorithm>
#include <fstream>
#include <iostream>
#include <string>
#include <vector>

// Fixture is generated by real OpenFHE, and added as HLS testbench data.
// Replay exactly the same bytes against checkpoint and shared RTL.
int main() {
    std::ifstream fixture("openfhe_rtl_fixture.txt");
    std::string magic;
    int calls = 0;
    if (!(fixture >> magic >> calls) || magic != "HKS_OPENFHE_RTL_V1" || calls != 3) {
        std::cerr << "Invalid OpenFHE fixture header\n";
        return 1;
    }
    constexpr uint64_t guard = 0xBAD0BAD0BAD0BAD0ULL;
    size_t compared = 0;
    for (int index = 0; index < calls; ++index) {
        int op, count, start;
        size_t aSize, bSize, cSize;
        if (!(fixture >> op >> count >> start >> aSize >> bSize >> cSize)) return 1;
        const bool init = index == 0;
        if ((init && (op != 0 || count != 0 || start != 0 || aSize != 196617 ||
                      bSize != 196614 || cSize != 0)) ||
            (!init && (op != 8 || count != (index == 1 ? 2 : 1) ||
                       start != (index == 1 ? 0 : 2) ||
                       aSize != size_t(count) * 4096 || bSize != 18 || cSize != 20480))) {
            std::cerr << "Invalid fixture descriptor\n";
            return 1;
        }
        std::vector<uint64_t> a(196617, guard), b(196614, guard), out(32768, guard), expected(cSize);
        for (size_t i = 0; i < aSize; ++i) if (!(fixture >> a[i])) return 1;
        for (size_t i = 0; i < bSize; ++i) if (!(fixture >> b[i])) return 1;
        for (auto& value : expected) if (!(fixture >> value)) return 1;
        const auto originalA = a, originalB = b;
        Top(a.data(), b.data(), out.data(), uint8_t(op), count, start);
        if (a != originalA || b != originalB ||
            !std::all_of(out.begin() + cSize, out.end(), [=](uint64_t x) { return x == guard; })) {
            std::cerr << "Fixture input/output guard failure\n";
            return 1;
        }
        for (size_t i = 0; i < cSize; ++i) {
            if (out[i] != expected[i]) {
                std::cerr << "OpenFHE oracle mismatch: transaction=" << index << " word=" << i << '\n';
                return 1;
            }
        }
        compared += cSize;
        std::cout << "[RTL PERF PASS] transaction=" << index << " opcode=" << op
                  << " alpha=" << count << " start=" << start << " words=" << cSize << '\n';
    }
    std::string extra;
    if (fixture >> extra) return 1;
    std::cout << "[OPENFHE RTL PASS] " << compared << " residues exactly match the CPU oracle\n";
    return 0;
}
